package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"text/template"
)

type Package struct {
	Name    string
	Dir     string
	Structs []Struct
}

type Struct struct {
	Name   string
	Fields []Field
}

type Field struct {
	Name string
	Type string
}

const templateStr = `
// Code generated by reset generator; DO NOT EDIT.

package {{.Name}}

{{range .Structs}}
func (r *{{.Name}}) Reset() {
	if r == nil {
		return
	}

{{range .Fields}}{{ResetField .}}{{end}}
}
{{end}}
`

var tmpl = template.Must(template.New("reset").
	Funcs(template.FuncMap{
		"ResetField": resetField,
	}).
	Parse(templateStr))

func main() {
	root := os.Args[1]

	packages := make(map[string]*Package)
	err := filepath.Walk(root, func(path string, info fs.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if !strings.HasSuffix(path, ".go") ||
			strings.HasSuffix(path, "_test.go") ||
			strings.HasSuffix(path, ".gen.go") {
			return nil
		}

		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			panic(err)
		}

		pkgName := f.Name.Name

		pkg, ok := packages[pkgName]
		if !ok {
			pkg = &Package{Name: pkgName, Dir: filepath.Dir(path)}
			packages[pkgName] = pkg
		}

		structs := findResetStructs(f)
		for _, s := range structs {
			pkg.Structs = append(pkg.Structs, s)
		}

		return nil
	})

	if err != nil {
		panic(err)
	}

	for _, p := range packages {
		if len(p.Structs) == 0 {
			continue
		}
		err := generateFile(p)
		if err != nil {
			panic(err)
		}
	}
}

func generateFile(packages *Package) error {
	var buf bytes.Buffer
	err := tmpl.Execute(&buf, packages)
	if err != nil {
		return fmt.Errorf("execute template: %w", err)
	}
	bufFmt, err := format.Source(buf.Bytes())
	if err != nil {
		return fmt.Errorf("format generated code: %w\n\n%s", err, buf.String())
	}

	out := filepath.Join(packages.Dir, "reset.gen.go")
	return os.WriteFile(out, bufFmt, 0o644)
}

func findResetStructs(file *ast.File) []Struct {
	if file == nil {
		return nil
	}

	var result []Struct
	for _, d := range file.Decls {
		var gd *ast.GenDecl
		var ok bool
		if gd, ok = d.(*ast.GenDecl); !ok {
			continue
		}
		if gd.Tok != token.TYPE {
			continue
		}

		if !hasResetComment(gd.Doc) {
			continue
		}

		for _, spec := range gd.Specs {
			specType, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}

			structType, ok := specType.Type.(*ast.StructType)
			if !ok {
				continue
			}

			s := Struct{
				Name: specType.Name.Name,
			}

			for _, field := range structType.Fields.List {
				if len(field.Names) == 0 {
					continue
				}

				s.Fields = append(s.Fields, Field{
					Name: field.Names[0].Name,
					Type: typeToString(field.Type),
				})
			}
			result = append(result, s)
		}
	}
	return result
}

func hasResetComment(doc *ast.CommentGroup) bool {
	if doc == nil {
		return false
	}

	for _, comment := range doc.List {
		if strings.Contains(comment.Text, "generate:reset") {
			return true
		}
	}
	return false
}

func typeToString(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name

	case *ast.StarExpr:
		return "*" + typeToString(t.X)

	case *ast.ArrayType:
		return "[]" + typeToString(t.Elt)

	case *ast.MapType:
		return "map[" + typeToString(t.Key) + "]" + typeToString(t.Value)

	default:
		return ""
	}
}

func resetField(f Field) string {
	switch {
	case strings.HasPrefix(f.Type, "map["):
		return fmt.Sprintf("\tclear(r.%s)\n", f.Name)

	case strings.HasPrefix(f.Type, "[]"):
		return fmt.Sprintf("\tr.%s = r.%s[:0]\n", f.Name, f.Name)

	case strings.HasPrefix(f.Type, "*"):
		return resetPointer(f)
	}

	return resetValue(f)
}

func resetPointer(f Field) string {
	inner := strings.TrimPrefix(f.Type, "*")

	switch inner {
	case "int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"float32", "float64":
		return fmt.Sprintf(
			"\tif r.%s != nil {\n\t\t*r.%s = 0\n\t}\n",
			f.Name, f.Name,
		)

	case "string":
		return fmt.Sprintf(
			"\tif r.%s != nil {\n\t\t*r.%s = \"\"\n\t}\n",
			f.Name, f.Name,
		)

	case "bool":
		return fmt.Sprintf(
			"\tif r.%s != nil {\n\t\t*r.%s = false\n\t}\n",
			f.Name, f.Name,
		)

	default:
		return fmt.Sprintf(
			"\tif r.%s != nil {\n\t\tr.%s.Reset()\n\t}\n",
			f.Name, f.Name,
		)
	}
}

func resetValue(f Field) string {
	switch f.Type {
	case "int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"float32", "float64":
		return fmt.Sprintf("\tr.%s = 0\n", f.Name)

	case "string":
		return fmt.Sprintf("\tr.%s = \"\"\n", f.Name)

	case "bool":
		return fmt.Sprintf("\tr.%s = false\n", f.Name)

	default:
		return fmt.Sprintf("\t// TODO: unsupported field %s %s\n", f.Name, f.Type)
	}
}
